export function BulkEditing({
  heading = "{{heading}}",
  selectedCount = {{selectedCount}},
  accent = "{{accent}}",
  action = "{{action}}",
  showToolbar = {{showToolbar}},
}) {
  const btnStyle = {
    background: action === "archive" ? "transparent" : accent,
    border: action === "archive" ? `1.5px solid ${accent}` : "none",
    borderRadius: action === "export" ? 999 : 6,
    padding: "5px 10px", font: "inherit", fontWeight: 600, cursor: "pointer", color: "#241430",
  };
  return (
    <section aria-label={`${heading} bulk editing`} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 380, width: 380, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      {showToolbar && (
        <div role="toolbar" aria-label="Bulk actions" style={{ display: "flex", alignItems: "center", gap: 8, background: "#fff", border: `1.5px solid ${accent}`, borderRadius: 8, padding: "8px 10px", marginBottom: 10, flexWrap: "wrap" }}>
          <span role="status" style={{ fontWeight: 700, marginRight: 4 }}>{selectedCount} selected</span>
          <button type="button" style={btnStyle}>Set status</button>
          <button type="button" style={btnStyle}>Archive</button>
          <button type="button" style={btnStyle}>Export</button>
        </div>
      )}
      <table style={{ borderCollapse: "collapse", width: "100%" }}>
        <thead><tr><th scope="col" style={{ textAlign: "left", padding: 8 }}><span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>Select</span></th><th scope="col" style={{ textAlign: "left", padding: 8 }}>Invoice</th><th scope="col" style={{ textAlign: "left", padding: 8 }}>Status</th></tr></thead>
        <tbody>
          <tr><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}><input type="checkbox" defaultChecked aria-label="Select INV-1042" /></td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>INV-1042</td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>Draft</td></tr>
          <tr><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}><input type="checkbox" defaultChecked aria-label="Select INV-1041" /></td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>INV-1041</td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>Draft</td></tr>
          <tr><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}><input type="checkbox" aria-label="Select INV-1040" /></td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>INV-1040</td><td style={{ padding: 8, borderBottom: "1px solid #24143014" }}>Sent</td></tr>
        </tbody>
      </table>
    </section>
  );
}
